import json
import re
from docx import Document

def delete_paragraph(paragraph):
    try:
        p = paragraph._element
        p.getparent().remove(p)
        paragraph._p = paragraph._element = None
    except Exception as e:
        print(f"Error deleting paragraph: {e}")

def replace_in_paragraph(para, data):
    text = para.text
    # Regex to find {{KEY}}
    # We use a pattern that matches {{KEY}}
    pattern = r'\{\{([A-Z_]+)\}\}'
    matches = re.findall(pattern, text)
    if not matches:
        return

    new_text = text
    changed = False
    for key in matches:
        placeholder = '{{' + key + '}}'
        if key in data:
            val = data[key]
            # Replace logic
            if placeholder in new_text:
                new_text = new_text.replace(placeholder, str(val))
                changed = True
        elif key == 'IF_RELOCATION' or key == 'END_IF_RELOCATION':
            # These should have been handled or added to data, but if they linger (e.g. if we didn't add them to data for some reason), 
            # we might want to ignore them or handle them.
            # In 'Yes' case, we added them to data as "".
            # In 'No' case, we deleted the paragraphs.
            pass

    if changed and new_text != text:
        # Rebuild runs to avoid split run issues
        # This implementation removes all formatting from the paragraph except what's on the first run
        # A more robust one might try to preserve formatting, but usually for placeholders replacing the whole text or being consistent is fine.
        # The skill's robust method:
        if para.runs:
            para.runs[0].text = new_text
            for run in para.runs[1:]:
                run.text = ''

def main():
    data_path = '/root/employee_data.json'
    template_path = '/root/offer_letter_template.docx'
    output_path = '/root/offer_letter_filled.docx'

    with open(data_path, 'r') as f:
        data = json.load(f)

    doc = Document(template_path)

    # Handle Relocation Conditional
    reloc_package = data.get('RELOCATION_PACKAGE', 'No')

    # Identify the range for conditional block
    paras = list(doc.paragraphs)
    start_index = -1
    end_index = -1

    for i, para in enumerate(paras):
        if '{{IF_RELOCATION}}' in para.text:
            start_index = i
        if '{{END_IF_RELOCATION}}' in para.text:
            end_index = i

    if start_index != -1 and end_index != -1:
        if reloc_package == 'Yes':
            # Case YES: Keep content, remove markers.
            # We achieve this by mapping the markers to empty strings in the data dict
            # and letting the generic replacer handle it.
            data['IF_RELOCATION'] = ""
            data['END_IF_RELOCATION'] = ""
        else:
            # Case NO: Remove content and markers.
            # Delete paragraphs from start_index to end_index
            to_delete = paras[start_index : end_index + 1]
            for p in to_delete:
                delete_paragraph(p)

    # Generic Replacement
    # 1. Body Paragraphs
    for para in doc.paragraphs:
        replace_in_paragraph(para, data)

    # 2. Tables
    for table in doc.tables:
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    replace_in_paragraph(para, data)
                # Nested tables
                for nested_table in cell.tables:
                     for nrow in nested_table.rows:
                        for ncell in nrow.cells:
                            for npara in ncell.paragraphs:
                                replace_in_paragraph(npara, data)

    doc.save(output_path)
    print(f"Generated {output_path}")

if __name__ == '__main__':
    main()

